actions.script:
const out = ec.service.sync().name('ironstone.comms.InboxServices.save#MessageFiles').parameters({store: store || '', id: id || null,
    emailMessageId: emailMessageId || null, communicationEventId: communicationEventId || null, driveId: driveId || '', path: path || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {savedList: out.savedList, failedList: out.failedList})

const out = ec.service.sync().name('ironstone.comms.InboxServices.get#MessageAttachment').parameters({store: store || '', id: id || ''}).call()
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true' && out.inlineAllowed)

const out = ec.service.sync().name('ironstone.comms.InboxServices.get#ContactCard').parameters({emailAddress: emailAddress || null,
    partyId: partyId || null, name: name || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {card: out.card})

const out = ec.service.sync().name('mantle.marketing.ContactListServices.find#ContactLists').parameters({contactListTypeEnumId: 'MAILBOX',
    searchText: searchText || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {contactListList: out.contactListList})

const out = ec.service.sync().name('ironstone.comms.InboxServices.unlink#ThreadRecord').parameters({emailMessageId: emailMessageId || null,
    communicationEventId: communicationEventId || null, recordEntityName: recordEntityName || '', recordId: recordId || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {unlinked: out.unlinked})

const out = ec.service.sync().name('ironstone.comms.InboxServices.prepare#CreateFromMessage').parameters({kind: kind || '',
    emailMessageId: emailMessageId || null, communicationEventId: communicationEventId || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {url: out.url, communicationEventId: out.communicationEventId})

const out = ec.service.sync().name('ironstone.comms.InboxServices.store#TrustedSender').parameters({emailAddress: emailAddress || '',
    remove: String(remove) === 'true'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {trustedSenders: out.trustedSenders})

const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.unsubscribe#Message').parameter('emailMessageId', emailMessageId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {method: out.method, unsubscribed: out.unsubscribed, url: out.url,
    messageInfos: out.unsubscribed ? [{type: 'success', message: ec.l10n.localize('Unsubscribed')}] : []})

const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.block#Sender').parameter('emailMessageId', emailMessageId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {emailRuleId: out.emailRuleId, movedCount: out.movedCount,
    messageInfos: [{type: 'success', message: ec.l10n.localize('Sender blocked: their mail goes to Spam')}]})

const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.store#EmailSearch').parameters({emailSearchId: emailSearchId || null,
    searchName: searchName || '', queryText: queryText || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {emailSearchId: out.emailSearchId})

const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.create#EmailLabel').parameters({emailAccountId: emailAccountId || '',
    labelName: labelName || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {emailLabelId: out.emailLabelId})

const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.create#EmailFolder').parameters({emailAccountId: emailAccountId || '',
    folderName: folderName || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {emailFolderId: out.emailFolderId})

const out = ec.service.sync().name('mantle.marketing.ContactListServices.join#ContactList').parameter('contactListId', contactListId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId, messageInfos: [{type: 'success',
    message: ec.l10n.localize(out.statusId === 'CLPT_PENDING' ? 'Asked to join: an owner will answer' : 'Joined')}]})

const out = ec.service.sync().name('mantle.marketing.ContactListServices.set#ContactListPartyDelivery').parameters({contactListId: contactListId || '',
    deliveryEnumId: deliveryEnumId || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {effectiveDeliveryEnumId: out.effectiveDeliveryEnumId})

const out = ec.service.sync().name('mantle.marketing.ContactListServices.add#ContactListParty').parameters({contactListId: contactListId || '',
    partyId: partyId || '', roleTypeId: roleTypeId || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId})
